/**
 * @param {number} m
 * @param {number} n
 * @param {number[]} hFences
 * @param {number[]} vFences
 * @return {number}
 */
var maximizeSquareArea = function (m, n, hFences, vFences) {
    const MOD = 1000000007;

    const getEdges = (fences, border) => {
        const set = new Set();
        const list = [...fences];

        list.push(1);
        list.push(border);
        list.sort((a, b) => a - b);

        for (let i = 0; i < list.length; i++) {
            for (let j = i + 1; j < list.length; j++) {
                set.add(list[j] - list[i]);
            }
        }

        return set;
    };

    const hEdges = getEdges(hFences, m);
    const vEdges = getEdges(vFences, n);

    let res = 0;

    for (const e of hEdges) {
        if (vEdges.has(e)) {
            res = Math.max(res, e);
        }
    }

    if (res === 0) {
        return -1;
    }

    return Number((BigInt(res) * BigInt(res)) % BigInt(MOD));
};

/**
 * @param {number} m
 * @param {number} n
 * @param {number[]} hFences
 * @param {number[]} vFences
 * @return {number}
 */
var maximizeSquareArea = function(m, n, hFences, vFences) {
    hFences.push(1, m);
    vFences.push(1, n);

    hFences.sort((a, b) => a - b);
    vFences.sort((a, b) => a - b);

    const hSpace = new Set();

    for (let i = 0; i < hFences.length; i++) {
        for (let j = i + 1; j < hFences.length; j++) {
            hSpace.add(hFences[j] - hFences[i]);
        }
    }

    let maxSpace = 0;

    for (let i = 0; i < vFences.length; i++) {
        for (let j = i + 1; j < vFences.length; j++) {
            const vSpace = vFences[j] - vFences[i];

            if (vSpace > maxSpace && hSpace.has(vSpace)) {
                maxSpace = vSpace;
            }
        }
    }

    if (maxSpace === 0) {
        return -1;
    }

    const maxSpaceBigInt = BigInt(maxSpace);
    const MOD = BigInt(10 ** 9 + 7);

    return Number((maxSpaceBigInt * maxSpaceBigInt) % MOD);
};
